const dotB = new Dot({ point: B, color: WHITE });

const title = new Text({ text: 'Law of Cosines', color: WHITE, fontSize: 34 });
title.moveTo([0, 3.15, 0]);
const formula = new MathTex({ latex: 'c^2=a^2+b^2-2ab\\cos C' });
await formula.waitForRender();
formula.moveTo([0.2, -2.65, 0]);

const pyth = new Text({ text: 'Pythagorean part:  a² + b²', color: GREEN, fontSize: 20 });
pyth.moveTo([-3.55, 2.15, 0]);
const correction = new Text({ text: 'correction:  −2ab cos C', color: YELLOW, fontSize: 20 });
correction.moveTo([2.5, 2.15, 0]);

