  triangle.setVertices([vertexC, pointA(), freshB]);
  edgeA.setVertices([vertexC, freshB]);
  edgeB.setVertices([vertexC, pointA()]);
  edgeC.setVertices([pointA(), freshB]);
  dotB.moveTo(freshB);
}

const controls = new Controls(scene, { position: 'bottom-left', theme: 'dark', width: 270 });
controls.addSlider({
  label: 'Angle C (degrees)', min: 20, max: 150, value: 65, step: 1,
  onChange: (value) => {
    angle = value * Math.PI / 180;
    updateTriangle();
  }
});
controls.addButton({ label: 'Make C a right angle', onClick: () => {
